//! ▶️ The job machine drives one genuine preclaimed original turn.
use super::*;
fn original_step_span(before:RetainedCloneProgress,after:RetainedCloneProgress)->Result<RetainedCloneProgress,ValueError>{let(Some(copied_items),Some(copied_bytes),Some(retained_capacity_bytes),Some(released_bytes))=(after.copied_items.checked_sub(before.copied_items),after.copied_bytes.checked_sub(before.copied_bytes),after.retained_capacity_bytes.checked_sub(before.retained_capacity_bytes),after.released_bytes.checked_sub(before.released_bytes))else{return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"retained semantic step decreased its original receipt"))};Ok(RetainedCloneProgress{copied_items,copied_bytes,retained_capacity_bytes,released_bytes})}

/// ▶️ Drives a preclaimed actual producer and returns original nonterminal custody through its admitted caller place.
pub fn drive_step<'job,J:InteractiveJob+?Sized>(job:&'job mut J,cx:&mut StepContext<'_>,origin:&mut OriginalJobReturnReceiver,site:&'static str,stage:InteractiveStage,callback_verdict:&mut Option<semio_framework_trace::CallbackVerdict>)->Result<OriginalJobReturn<'job>,OriginalTurnFailure>{
 *callback_verdict=None;if !origin.prepare(cx)?{return Ok(OriginalJobReturn::Preparing)}let Some(mut claim)=origin.enter_body(cx)?else{return Ok(OriginalJobReturn::Preparing)};let before=cx.retained_progress();let reserved=cx.reserved_return_progress();let original=cx.retained_grant();let now=cx.clock_source();let watchdog=Watchdog::start_at(site,cx.operation(),cx.generation(),stage,cx.latest_us().or_else(||cx.now_us()));let result=job.step(cx,&mut claim);let after=cx.retained_progress();let end=now();cx.observe_step_clock(end);*callback_verdict=Some(watchdog.finish_at(end));
 let current=original_step_span(before,after).and_then(|physical|original_step_span(reserved,cx.reserved_return_progress()).and_then(|reserved|original_step_span(reserved,physical)));let receipt_qualification=match current{Err(error)=>Some(error.into()),Ok(delta)if !delta.fits(original)=>Some(ValueError::literal(ValueRefusalKind::InvariantViolated,"retained semantic step exceeds its original context").with_retained_progress(delta).into()),Ok(delta)=>match &result{InteractiveJobStep::Outcome(Some(outcome))=>{let admission=outcome.admission();(admission.operation()!=cx.operation()||admission.generation()!=cx.generation()||admission.progress().copied_items>delta.copied_items||admission.progress().copied_bytes>delta.copied_bytes).then(||ValueError::literal(ValueRefusalKind::InvariantViolated,"retained semantic outcome lacks its original current receipt").with_retained_progress(delta).into())},_=>None}};let returned=claim.finish(cx,result,receipt_qualification);
 if let OriginalJobReturn::Outcome(reply)=&returned{if let Some(outcome)=reply.original(){let stage=match outcome{JobOutcomeBorrow::Yield{..}=>None,JobOutcomeBorrow::PreviewReady{..}=>Some(semio_framework_trace::TraceStage::PreviewPublished),JobOutcomeBorrow::CheckpointReady{..}=>Some(semio_framework_trace::TraceStage::Checkpoint),JobOutcomeBorrow::Complete{..}=>Some(semio_framework_trace::TraceStage::Committed),JobOutcomeBorrow::Cancelled{..}=>Some(semio_framework_trace::TraceStage::Cancelled),JobOutcomeBorrow::Fault{..}=>Some(semio_framework_trace::TraceStage::Failed)};if let Some(stage)=stage{semio_framework_trace::record_trace_event_at(cx.operation(),cx.generation(),stage,end);}}}Ok(returned)
}
